def run(context):
    symbols = context['symbol_list']
    technical_scores = context['technical_scores']
    return {symbol: 'Bullish' if score > 70 else 'Neutral' for symbol, score in zip(symbols, technical_scores)}

def run(context):
    # List top VCP candidates based on VCP scores and recent performance metrics
    candidate_list = context['scores.stage2_vcp_picks']
    sorted_candidates = sorted(candidate_list, key=lambda x: (x['vcp_score'], x['relative_strength']), reverse=True)
    top_candidates = sorted_candidates[:10]  # Select top 10
    return {'primary_candidates': top_candidates}

def run(context):
    # Example Python tool that ranks companies based on PAT growth and margin improvements
    results = context
    ranked_results = sorted(results, key=lambda x: (x['growth_yoy_pat_pct'], x['opm_pct']), reverse=True)
    return {'ranking': ranked_results}
